buttonfield.script:
function onValueChanged()
	local node = window.getDatabaseNode();
	for _,v in pairs(DB.getChildren(node, "effects")) do
		if DB.getValue(v, "label", ""):match("MAGIC") then
			DB.setValue(v, "isactive", "number", getValue());
		end
		if DB.getValue(v, "label", ""):match("ANTI") then
			if getValue() == 1 then
				DB.setValue(v, "isactive", "number", 0);
			elseif getValue() == 0 then
				DB.setValue(v, "isactive", "number", 1);
			end
		end
	end
end
